-- =====================================================================
-- datos_contenedores_reales.sql -- Contenedores domiciliarios reales de
-- Montevideo (fuente: Intendencia de Montevideo, datos abiertos) + cuadrillas,
-- camiones, choferes, recolectores y maquinaria de prueba para cubrir los 8
-- municipios. Generado automaticamente -- ver nota sobre direcciones abajo.
--
-- Las coordenadas originales vienen en UTM (zona 21S) y se convirtieron a
-- lat/long. NO se pudo geocodificar cada punto a una direccion real (sin
-- acceso a internet en el entorno donde se genero este script), asi que la
-- 'direccion' es APROXIMADA: avenida principal de la zona/municipio + un
-- numero de puerta generado, no la direccion exacta real de cada contenedor.
-- =====================================================================

SET autocommit = 0;
START TRANSACTION;

-- ---- Rutas (una por circuito real del archivo municipal) ----
SET @ruta_first_id = LAST_INSERT_ID();

-- ---- Contenedores reales (todos los del archivo, en lotes) ----

-- ---- Camiones nuevos (1 por municipio, ademas de los 3 ya existentes) ----
SET @camion_first_id = LAST_INSERT_ID();

-- ---- Choferes nuevos (uno por municipio), contrasena test1234 ----

SET @chofer_first_id = LAST_INSERT_ID();

-- ---- Recolectores nuevos (uno por municipio) ----

SET @recolector_first_id = LAST_INSERT_ID();

-- ---- Cuadrillas nuevas (una por municipio) ----
SET @cuadrilla_first_id = LAST_INSERT_ID();


-- ---- Ruta habitual de cada cuadrilla: todos los circuitos de su municipio ----

-- ---- Maquinaria y repuestos extra ----
SET @repuesto_first_id = LAST_INSERT_ID();

SET @maquinaria_first_id = LAST_INSERT_ID();


COMMIT;